// Generated by OrchestKit Claude Plugin
// Created: 2026-07-16

/**
 * Display Lint — PreToolUse/Bash hook (transcript de-clutter, brainstorm 2026-07-16)
 *
 * CC renders every Bash call as a full-width tool card with the verbatim
 * command string, and offers no collapse/truncation setting (upstream
 * #67005/#75500 open, #38403 "not planned"). Long compound one-liners
 * (`cd /abs/path && sed -n '1,40p' f.ts && grep -n 'x' | head`) therefore
 * bury the assistant's narrative under command noise — the #1 transcript
 * complaint in this repo's sessions.
 *
 * This hook addresses the clutter at the SOURCE: a command that is both
 * long AND many-staged draws an advisory nudge to write a script file and
 * run that instead (one short tool card, and robust against terminal
 * line-wrap splitting flags from their args).
 *
 * ADVISORY, NOT A BLOCK (#2947). This shipped as a hard deny and the deny
 * was the wrong mechanism for a cosmetic concern: it blocked correct work,
 * including the very probes needed to debug this hook, and taught users to
 * reach for ORK_DISPLAY_LINT=0 (which disables the gate wholesale, exactly
 * the outcome it exists to prevent). It now warns and lets the command run.
 * The warning carries no permissionDecision, so it neither approves nor
 * denies: dangerous-command-blocker and the permission prompt still apply.
 *
 * Deliberately NOT fired on:
 *   - real heredoc-bearing commands (`<<EOF`, `<<'EOF'`, `<<-EOF`) — writing
 *     a script file IS the remedy, so the command that creates one must
 *     pass. Anchored to an actual delimiter so bash bit-shift (`1 << 4`)
 *     doesn't false-exempt an otherwise-cluttered command.
 *   - a command that IS ENTIRELY a script invocation
 *     (bash/sh/zsh/python/node <file>) — already compliant. Requires the
 *     WHOLE command to be the invocation, not merely present as one stage
 *     among several — `<clutter> && bash noop.sh` does not exempt the
 *     clutter before it.
 *   - long single-stage commands (e.g. `git commit -F msg.txt`) — length
 *     alone is not clutter; only compound chains defeat readability. This
 *     covers commands whose QUOTED payload holds shell metacharacters
 *     (`python3 -c "…"`, `git commit -m "a | b"`, `grep "a\|b"`): the shell
 *     sees one stage, so the lint must too (#2947).
 *   - ORK_DISPLAY_LINT=0 (env opt-out)
 *
 * Known, accepted limitation: `bash -c "<cluttered chain>"` counts as one
 * stage and is not flagged, since the chain lives inside a quoted payload.
 * Deliberately wrapping a chain to dodge an advisory nudge is self-defeating
 * (the clutter still renders). Revisit only if it shows up in real
 * transcripts.
 */

import type { HookInput, HookResult, HookContext } from '../../types.js';
import { outputSilentSuccess, outputPreToolModelHint } from '../../lib/common.js';
import { blankQuotedContent } from '../../lib/normalize-command.js';
import { NOOP_CTX } from '../../lib/context.js';
import { claimOncePerSession } from '../../lib/session-once.js';

const HOOK_NAME = 'pretool/bash/display-lint';

/** Flagging requires length STRICTLY over this. */
const MAX_DISPLAY_LENGTH = 200; // chars
/** Flagging requires stage count AT OR OVER this (2 stages is not clutter). */
const MIN_STAGES_TO_FLAG = 3; // shell stages (&&, ||, |, ;, newline)

/**
 * Shell stage separators, outside quotes and not backslash-escaped.
 *
 * The `(?<!\\)` guard is load-bearing: `grep -l a\|b` carries an escaped
 * pipe with no quotes anywhere, and bash reads it as a literal character.
 * Without the lookbehind the split manufactures stages that do not exist.
 */
const STAGE_SPLIT_RE = /\s*(?<!\\)(?:&&|\|\||\||;|\n)\s*/;

/**
 * Split a command into the stages BASH would see.
 *
 * Deliberately NOT normalizeCommand(): that is a SECURITY primitive whose
 * documented job is to "prevent bypass via quoting, escapes, and compound
 * operators". It strips quotes but keeps their content, and rewrites `\|`
 * into a real `|`, so that a `rm` hidden inside quotes still gets matched.
 * Correct for dangerous-command-blocker; inverted for a DISPLAY judgment,
 * where it counted `python3 -c "<7-line script>"` as 7 stages and denied a
 * single-stage command (#2947).
 *
 * Here the shell's own semantics apply, and BOTH halves are needed:
 *   1. blank quoted regions (operators inside them are payload), and
 *   2. never split on a backslash-escaped operator (it is a literal).
 * Blanking alone is insufficient: `grep -l a\|b` has no quotes at all.
 */
function splitDisplayStages(command: string): string[] {
  // Comments go before substitutions: an unmatched `$(` or backtick inside a
  // comment would otherwise blank every later line (CodeRabbit 4209092885).
  return blankSubstitutions(stripComments(blankQuotedContent(command)))
    .split(STAGE_SPLIT_RE)
    .map((s) => s.trim())
    .filter(Boolean);
}

/**
 * Blank the inside of `$( … )` and backtick command substitutions.
 *
 * A pipeline inside a substitution runs in a subshell; at the top level the
 * shell sees ONE word. `VAL=$(git rev-parse HEAD | cut -c1-8)` is one stage,
 * not two (ork-display-lint-bug-2026-10-07). Nesting is tracked so the first
 * `)` of an inner `$(…)` does not end the outer one. Runs after quoted
 * content is blanked, so a `)` inside quotes cannot close a substitution.
 */
function blankSubstitutions(command: string): string {
  const out = command.split('');
  let depth = 0;
  let inBacktick = false;
  for (let i = 0; i < out.length; i++) {
    const ch = command[i];
    if (!inBacktick && ch === '$' && command[i + 1] === '(') {
      if (depth > 0) out[i] = ' ';
      depth++;
      i++;
      if (depth > 1) out[i] = ' ';
      continue;
    }
    if (depth > 0) {
      if (ch === '(') depth++;
      else if (ch === ')') depth--;
      if (depth > 0) out[i] = ' ';
      continue;
    }
    if (ch === '`' && command[i - 1] !== '\\') {
      inBacktick = !inBacktick;
      continue;
    }
    if (inBacktick) out[i] = ' ';
  }
  return out.join('');
}

/**
 * Drop shell comments: a `#` that starts a word, through the end of its line.
 *
 * Comment lines are documentation, not stages, and the operators they mention
 * (`# build && test | ship`) are prose. Counting them turned a one-command
 * call into an 8-stage "offender" (ork-display-lint-bug-2026-10-07). A `#`
 * glued to a word (`$#`, `${#x}`, `a#b`) is not a comment and stays.
 */
function stripComments(command: string): string {
  return command.replace(/(^|[\s;&|(])#[^\n]*/g, '$1');
}

/**
 * The shell the Bash tool runs commands in. Claude Code uses
 * CLAUDE_CODE_SHELL when set, otherwise the login shell in SHELL. Returns
 * the basename (`zsh`, `bash`, …) or '' when neither is set.
 */
function toolShell(): string {
  const raw = process.env.CLAUDE_CODE_SHELL || process.env.SHELL || '';
  return raw.split('/').pop()?.toLowerCase() ?? '';
}

/** Commands that already follow the script-file pattern. */
const SCRIPT_INVOCATION_RE =
  /^(bash|sh|zsh|python3?|node)\s+(\$\{?[A-Za-z_][A-Za-z0-9_]*\}?\/)?\S*\.(sh|bash|py|mjs|js|ts)\b/;

// Reading a file back: the other half of "run a script, look at its output".
// Anchored and argument-shaped, so `cat x.log` matches and `cat x | jq ...`
// does not (the jq lands in its own stage and disqualifies the command).
const FILE_PEEK_RE = /^(?:cat|tail|head|wc|less|sed\s+-n)\s+(?:-\S+\s+)*\S+\s*$/;

// Cleaning the file up afterwards.
const FILE_REMOVE_RE = /^rm\s+(?:-[A-Za-z]+\s+)*\S+\s*$/;

/**
 * Is this stage pure plumbing around a script file: running one, reading one
 * back, or deleting one?
 *
 * This exists because the hook was nudging the exact shape it recommends
 * (#3936). `bash <path>/x.sh > <path>/out.log 2>&1; tail -1 <path>/out.log; rm
 * <path>/out.log` is three stages of script-file plumbing and nothing else,
 * but it tripped the lint at 538 characters, because under `$TMPDIR` on macOS
 * a single absolute path is 60+ characters before any flag. Length was
 * measuring path verbosity, not command clutter, and the advice it gave back
 * ("write the steps to a script and run that") was already followed.
 */
function isPlumbingStage(stage: string): boolean {
  return (
    SCRIPT_INVOCATION_RE.test(stage) || FILE_PEEK_RE.test(stage) || FILE_REMOVE_RE.test(stage)
  );
}

// A real heredoc delimiter starts with a letter, underscore, or quote —
// `<< 4`, `<<4`, `<< $n` (bash arithmetic shift / bareword) never match,
// so `console.log(1 << 4)` correctly stays out of the exemption.
const HEREDOC_RE = /<<-?~?\s*(['"][A-Za-z_][A-Za-z0-9_]*['"]|[A-Za-z_][A-Za-z0-9_]*)/;

/**
 * The once-per-session store, injected so the handler owns no file I/O
 * (FH-ready). The default writes a flag file under .claude/state.
 */
export interface DisplayLintDeps {
  claimOnce: (projectDir: string, name: string, sessionId: string) => boolean;
}

const DEFAULT_DEPS: DisplayLintDeps = { claimOnce: claimOncePerSession };

/**
 * True the first time this session flags a command, false after (#4652).
 *
 * The advice is the same paragraph every time, and a polling loop of long
 * commands repeated it on every call. One copy per session teaches the model;
 * the rest is noise. Without a session id there is no session to key on, so
 * the hint is not limited.
 */
function firstHintThisSession(input: HookInput, ctx: HookContext, deps: DisplayLintDeps): boolean {
  if (!input.session_id) return true;
  return deps.claimOnce(input.project_dir || ctx.projectDir, 'display-lint', input.session_id);
}

export function displayLint(
  input: HookInput,
  ctx: HookContext = NOOP_CTX,
  deps: DisplayLintDeps = DEFAULT_DEPS,
): HookResult {
  if (process.env.ORK_DISPLAY_LINT === '0') return outputSilentSuccess();

  const command = input.tool_input?.command || '';
  if (!command || command.length <= MAX_DISPLAY_LENGTH) return outputSilentSuccess();

  // Heredocs are how script files get created — never lint the remedy.
  if (HEREDOC_RE.test(command)) return outputSilentSuccess();

  const stages = splitDisplayStages(command);

  // Already following the script-file pattern — compliant only when EVERY
  // stage is plumbing (run a script, read a file back, delete it). Matching
  // "anywhere in the command" let `<clutter> && bash noop.sh` (the noop need
  // not even exist) bypass the lint for everything before it, the exact
  // clutter this hook targets. Requiring ALL stages keeps that property: one
  // non-plumbing stage disqualifies the whole command, so the bypass is still
  // impossible, while the recommended shape stops being nudged (#3936).
  if (stages.every(isPlumbingStage)) return outputSilentSuccess();

  if (stages.length < MIN_STAGES_TO_FLAG) return outputSilentSuccess();

  ctx.log(HOOK_NAME, `flagged: ${command.length} chars / ${stages.length} stages`);

  if (!firstHintThisSession(input, ctx, deps)) return outputSilentSuccess();

  // Advisory, NOT a permission decision: the command runs. The hint reaches
  // Claude only (additionalContext), which is what shifts future calls toward
  // script files. A systemMessage copy repeated it in the user's transcript
  // and gave the user nothing to act on (#4652). outputAllowWithContext()
  // would have set permissionDecision:'allow' and skipped the permission
  // prompt as a side effect of a cosmetic lint.
  // The zsh clause is true only where the Bash tool shell IS zsh. On a bash
  // host (Linux, or CLAUDE_CODE_SHELL=bash) it was wrong advice about a trap
  // that host does not have (ork-display-lint-bug-2026-10-07).
  const zshClause =
    toolShell() === 'zsh'
      ? ', and gets real bash word splitting (the Bash tool shell here is zsh, where an unquoted $var never word-splits, so a loop over $var runs once on the whole string and every iteration gets a malformed argument)'
      : '';
  return outputPreToolModelHint(
    `[display-lint] ${command.length} chars across ${stages.length} stages. A script file renders as one short tool card and is safe from line-wrap splitting a flag from its argument${zshClause}: write the steps to <scratchpad>/<task>.sh and run that. (Silence: export ORK_DISPLAY_LINT=0)`,
  );
}
